// Reads the uploaded .md / .txt file as UTF-8 text.
const item = $input.first();
const keys = Object.keys(item.binary || {});
if (!keys.length) throw new Error('No file was uploaded.');
const buf = await this.helpers.getBinaryDataBuffer(0, keys[0]);
return [{ json: { ...item.json, stories_text: buf.toString('utf8'), file_name: item.binary[keys[0]].fileName || '' } }];

// Splits the pasted RICK list into one item per story and drops exact duplicates of rows already in the sheet.
const cfg = $('Config').first().json;
const text = String(cfg.stories_text || '').replace(/\r/g, '').replace(/ /g, ' ').replace(/\\([\\`*_{}\[\]()#+\-.!'"])/g, '$1').replace(/\*\*|__/g, '').replace(/^#{1,6}\s*/gm, '').trim();
const rows = $('Read queue').all().map(r => r.json).filter(r => r && r.post_id);
let maxNum = 0;
for (const r of rows) { const m = String(r.post_id).match(/QDE-FC-(\d+)/i); if (m) maxNum = Math.max(maxNum, +m[1]); }
const norm = s => String(s || '').toLowerCase().normalize('NFKD').replace(/[̀-ͯ]/g, '').replace(/[^a-z0-9 ]+/g, ' ').replace(/\s+/g, ' ').trim();
const existingKeys = new Set(rows.flatMap(r => [norm(r.title), norm(r.headline)]).filter(Boolean));
const existingList = rows.map(r => `${r.post_id}: ${r.title || ''} | ${r.headline || ''}`).join('\n');

let blocks;
if (/^\s*\d{1,2}\s*[.)]\s+/m.test(text)) {
  blocks = text.split(/^\s*\d{1,2}\s*[.)]\s+/m).slice(1);
} else {
  blocks = text.split(/\n\s*\n/);
}
blocks = blocks.map(b => b.replace(/\s+/g, ' ').trim()).filter(b => b.length >= 30);

const isCaps = s => { const L = s.replace(/[^A-Za-z]/g, ''); return L.length >= 4 && L.replace(/[^A-Z]/g, '').length / L.length > 0.8; };
const out = [], skipped = [];
blocks.forEach((b, i) => {
  const segs = b.split(/\s+(?:[—–]|-{1,3})\s+/);
  const title = (segs[0] || '').trim();
  let second = '', rest = segs.slice(1);
  if (rest.length && isCaps(rest[0])) { second = rest[0].trim(); rest = rest.slice(1); }
  const pitch = rest.join(' — ').trim();
  if (existingKeys.has(norm(title))) { skipped.push(`${title} (already in sheet)`); return; }
  out.push({ json: { n: i + 1, rick_title: title, rick_second: second, pitch, raw: b, existing_list: existingList, next_num: maxNum + 1 } });
});
if (!out.length) return [{ json: { none: true, skipped, next_num: maxNum + 1 } }];
out.forEach(o => o.json.pre_skipped = skipped);
return out;

// One Responses API call per story, with web search. Research rules come from GitHub (Research Prompt v2).
const cfg = $('Config').first().json;
const researchMd = $('Fetch research prompt').first().json.research_md || '';
const s = $json;
const instructions = `You are Claude-in-the-pipeline running the QDE Famous-Case Research Prompt below inside an automated n8n run.

AUTOMATED-RUN OVERRIDES (these win over the file where they differ):
1. The candidate is already chosen. Bart picked it and RICK already wrote its title. Do NOT search for or score other candidates (skip §3). Run §1 (all five gates), the §2 dedupe against the existing rows listed in the input, and §4 (verify and write the fact card) for THIS story only.
2. Use web search. Read past the first result. Every fact needs a source you actually opened; two independent sources for any number, date or sentence length, otherwise it goes under a warning line. Never write a fact from memory. Wikipedia is a map, not a source.
3. If any gate fails, or the case is already in the sheet under another name, decision is REJECT and you say which gate and why in one sentence.
4. Do NOT write a headline, caption or image prompt.
5. Output ONLY one JSON object, no prose, no code fence, with exactly these keys:
{
 "decision": "ACCEPT" or "REJECT",
 "reject_reason": "" or one sentence naming the failed gate,
 "duplicate_of": "" or the existing post_id,
 "title": "case name for humans, e.g. 'Velvalee Dickinson, the Doll Woman'",
 "beat": "one beat from the §1 rotation list",
 "torn_note": "3 to 4 short fragments separated by ' · '",
 "face_source": "the SCENE field: who is in frame and how to describe them (decade, expression, clothing, mood), or why nobody is; plus period, setting and props. Positive statements only.",
 "facts_need_verify": "YES" if any warning line remains, else "NO",
 "fact_status": "the sourced narrative (CASE, WHEN/WHERE, THE DOCUMENT, THE CRIME, THE TELL, THE OUTCOME, THE DETAILS, SOURCES with URLs), then every unverified item on its own line starting with the ⚠️ symbol",
 "sources": [{"url": "...", "supports": "..."}]
}

===== QDE_FamousCase_Research_Prompt_v2.md =====
${researchMd}`;
const input = `STORY FROM BART (via RICK):
Title: ${s.rick_title}
${s.rick_second ? 'Second line: ' + s.rick_second + '\n' : ''}Pitch: ${s.pitch}

EXISTING ROWS IN QDE_Post_Queue (post_id: title | headline):
${s.existing_list}`;
return { json: { ...s, body: { model: cfg.model, tools: [{ type: 'web_search_preview', search_context_size: 'high' }], instructions, input, temperature: 0.2 } } };

// Pull the model's JSON out of the Responses API output; keep the story fields alongside.
const s = $('Build research request').item.json;
const r = $json;
let text = '';
const cites = [];
for (const o of (r.output || [])) {
  if (o.type === 'message') for (const c of (o.content || [])) {
    if (c.type === 'output_text') { text += c.text; for (const a of (c.annotations || [])) if (a.url) cites.push(a.url); }
  }
}
let d = null, err = '';
if (r.error) err = 'OpenAI error: ' + (r.error.message || JSON.stringify(r.error));
else {
  const m = text.replace(/```json|```/g, '').match(/\{[\s\S]*\}/);
  try { d = JSON.parse(m ? m[0] : text); } catch (e) { err = 'Could not parse research JSON'; }
}
const base = { n: s.n, rick_title: s.rick_title, rick_second: s.rick_second, pitch: s.pitch, next_num: s.next_num, pre_skipped: s.pre_skipped || [] };
if (!d) return { json: { ...base, decision: 'ERROR', reject_reason: err } };
if (!/^(ACCEPT|REJECT)$/.test(d.decision)) d.decision = 'REJECT';
if ((!d.sources || !d.sources.length) && cites.length) d.sources = [...new Set(cites)].map(u => ({ url: u, supports: '' }));
if (d.decision === 'ACCEPT' && (!d.sources || !d.sources.length)) { d.decision = 'REJECT'; d.reject_reason = 'No sources returned by web search — not written.'; }
return { json: { ...base, ...d } };

// Stage B copy (and gold word / sub-line) from GitHub: Story Prompt V4 + Headline rules + names + voice.
const cfg = $('Config').first().json;
const story = $('Fetch story prompt').first().json.story_md || '';
const head = $('Fetch headline rules').first().json.headline_md || '';
const names = $('Fetch names file').first().json.names_md || '';
const voice = $('Fetch Bart voice').first().json.voice_md || '';
const d = $json;
const narrative = String(d.fact_status || '').split(/\n?\s*⚠️/)[0].trim();
const sys = `You are Peggy, the copywriter, running inside an automated n8n workflow for the QDE famous-case post queue.

AUTOMATED-RUN OVERRIDES (these win over the files where they differ):
1. Stage A is DONE. Bart already ran RICK. The headline is supplied. Column D = the supplied headline, verbatim, in ALL CAPS. Only correct the spelling of a proper noun or accent. Never reword, shorten or lengthen it.
2. YOU write, following the rules in Headline-QDE-Post.md:
   - gold_word: 1 to 3 words that appear VERBATIM in the headline. Prefer the concrete noun or crime word.
   - subline: the second shock, two short beats, under twelve words, supported by the facts. If Bart supplied a second RICK line, use it as the basis when the facts support it.
3. Then write Stage B of QDE_FamousCase_Story_Prompt_V4.md exactly: image_prompt (B1 house shape; quote the headline and gold word exactly as in D and E; quote the torn-note fragments verbatim and state the count; subject from face_source; positive statements only, no negation words outside quotation marks) and caption (B2: under 200 words before the CTA, five parts, "I wasn't involved in the ___ case.", the exact CTA block, then exactly five hashtags on one line).
4. Use ONLY facts in the sourced narrative supplied. Never use anything from the warning lines. Never invent a fact, a quote or a Bart opinion.
5. Return ONLY a JSON object with keys: headline, gold_word, subline, image_prompt, caption.

===== QDE_FamousCase_Story_Prompt_V4.md =====
${story}

===== Headline-QDE-Post.md =====
${head}

===== Peggy_Copy_Names_and_Spelling_v1.md =====
${names}

===== BART_BAGGETT_VOICE.MD =====
${voice}`;
const user = `SUPPLIED HEADLINE (RICK): ${d.rick_title}
${d.rick_second ? 'SUPPLIED SECOND LINE (RICK): ' + d.rick_second + '\n' : ''}CASE (column B): ${d.title}
TORN NOTE (column G): ${d.torn_note}
SCENE (column H): ${d.face_source}
SOURCED NARRATIVE (from column N, warnings removed):
${narrative}`;
return { json: { ...d, body: { model: cfg.model, temperature: 0.4, response_format: { type: 'json_object' },
  messages: [{ role: 'system', content: sys }, { role: 'user', content: user }] } } };

// Completeness gate (Story Prompt V4) — repair or flag, never block. Assigns post_ids in story order.
const cfg = $('Config').first().json;
const reqs = $('Build copy request').all().map(i => i.json);
const outs = $input.all().map(i => i.json);
const stamp = $now.setZone('America/Chicago').toFormat('yyyy-LL-dd HH:mm');
const words = s => String(s || '').trim().split(/\s+/).filter(Boolean).length;
const pairs = reqs.map((d, i) => ({ d, o: outs[i] })).sort((a, b) => a.d.n - b.d.n);
let num = reqs.length ? reqs[0].next_num : 1;
const rows = [];
for (const { d, o } of pairs) {
  const flags = [];
  let c = {};
  try { c = JSON.parse(o.choices[0].message.content); } catch (e) { flags.push('COPY NOT WRITTEN (OpenAI error)'); }
  let headline = String(c.headline || d.rick_title || '').toUpperCase().replace(/\s+/g, ' ').trim();
  const gold = String(c.gold_word || '').toUpperCase().trim();
  const subline = String(c.subline || '').trim();
  const J = String(c.image_prompt || '').trim();
  const L = String(c.caption || '').trim();
  const G = String(d.torn_note || '').trim();
  const H = String(d.face_source || '').trim();
  if (headline !== String(d.rick_title).toUpperCase().replace(/\s+/g, ' ').trim()) flags.push('HEADLINE CHANGED FROM RICK TEXT — check D');
  for (const [k, v] of Object.entries({ headline, gold_word: gold, subline, torn_note: G, face_source: H, image_prompt: J, caption: L })) if (!v) flags.push(`EMPTY ${k}`);
  if (words(headline) > 8) flags.push(`HEADLINE ${words(headline)} WORDS (max 8)`);
  if (gold && !headline.includes(gold)) flags.push('GOLD WORD NOT IN HEADLINE');
  if (words(gold) > 3) flags.push('GOLD WORD OVER 3 WORDS');
  if (words(subline) >= 12) flags.push(`SUBLINE ${words(subline)} WORDS (under 12)`);
  const frags = G.split('·').map(s => s.trim()).filter(Boolean).length;
  if (frags < 3 || frags > 4) flags.push(`TORN NOTE HAS ${frags} FRAGMENTS (3–4)`);
  if (J && !J.toUpperCase().includes(headline)) flags.push('IMAGE PROMPT DOES NOT QUOTE HEADLINE');
  if (J && gold && !J.toUpperCase().includes(gold)) flags.push('IMAGE PROMPT MISSING GOLD WORD');
  if (/\[\[|\]\]/.test(J + L)) flags.push('PLACEHOLDER BRACKETS');
  const unquoted = J.replace(/"[^"]*"|“[^”]*”/g, '');
  if (/\b(no|not|without|remove)\b/i.test(unquoted)) flags.push('NEGATION IN IMAGE PROMPT');
  const cta = '1-800-980-9030';
  const ci = L.indexOf(cta);
  if (ci < 0) flags.push('CTA MISSING');
  else {
    if (words(L.slice(0, ci)) >= 200) flags.push(`CAPTION ${words(L.slice(0, ci))} WORDS (under 200)`);
    if (!/1-800-980-9030\s*\n\s*HandwritingExpertUSA\.com · bartbaggett\.com/.test(L)) flags.push('CTA BLOCK NOT EXACT');
  }
  const tags = (L.match(/(^|\s)#[A-Za-z0-9_]+/g) || []).length;
  if (tags !== 5) flags.push(`${tags} HASHTAGS (need 5)`);
  if (!/I wasn[’']t involved in the /.test(L)) flags.push('MISSING "I wasn\'t involved" LINE');
  if (/handwritingexpert\.com/i.test(L)) flags.push('BANNED DOMAIN HandwritingExpert.com');
  if (/grapholog/i.test(L.replace(/#\S+/g, ''))) flags.push('GRAPHOLOGY IN BODY');
  if (L.includes('!')) flags.push('EXCLAMATION MARK');
  rows.push({
    post_id: `QDE-FC-${num++}`, title: d.title || d.rick_title, status: '',
    headline, gold_word: gold, subline, torn_note: G, face_source: H, photo_required: '',
    image_prompt: J, image_url: '', caption: L,
    facts_need_verify: d.facts_need_verify === 'NO' ? 'NO' : 'YES',
    fact_status: String(d.fact_status || ''),
    notes: `INTAKE ${stamp} (${cfg.submitted_by}) via Peggy story form | Flags: ${flags.join('; ') || 'none'}`
  });
}
return rows.map(r => ({ json: r }));

// Slack note for Katie: what was added, what was rejected, and her one job — type READY in column C.
const pick = n => { try { return $(n).all().map(i => i.json); } catch (e) { return []; } };
const added = pick('Gate + build rows');
const parsed = pick('Parse research');
const split = pick('Split stories');
const pre = (split[0] && split[0].pre_skipped) || (split[0] && split[0].skipped) || [];
const rejected = parsed.filter(p => p.decision !== 'ACCEPT');
const cfg = $('Config').first().json;
const sheet = 'https://docs.google.com/spreadsheets/d/' + cfg.sheet_id + '/edit#gid=0';
const lines = [];
if (added.length) {
  const first = added[0].post_id, last = added[added.length - 1].post_id;
  lines.push(`<@${cfg.ready_owner_slack_id}> ${added.length} new celebrity case${added.length === 1 ? '' : 's'} (${first}${added.length > 1 ? ' to ' + last : ''}) just landed in QDE_Post_Queue and need your review. Nothing happens with them until you mark them READY in column C. Please review the headline and mark READY to activate the story.`);
  lines.push('');
  lines.push('For each new row:');
  lines.push('1. Review columns D to F (headline, gold word, sub-line) with human eyes.');
  lines.push('2. Check column N (fact_status) for any ⚠️ lines, and the flags listed below.');
  lines.push('3. If it is good, type READY in column C (status), all caps, to activate the story.');
  lines.push('4. If it is not usable, leave column C blank and reply in this thread with the post_id and what is wrong.');
  lines.push('');
  for (const r of added) {
    const fl = (r.notes.split('Flags: ')[1] || 'none');
    lines.push(`• ${r.post_id} — ${r.headline} (${r.title}) · facts need verify: ${r.facts_need_verify} · flags: ${fl}`);
  }
  lines.push('');
  lines.push('Sheet: ' + sheet);
} else {
  lines.push('Peggy story intake finished: no new rows were added to QDE_Post_Queue.');
}
if (rejected.length || pre.length) {
  lines.push('');
  lines.push(`Not added (${rejected.length + pre.length}):`);
  for (const r of rejected) lines.push(`✗ ${r.rick_title} — ${r.decision === 'ERROR' ? 'ERROR: ' : ''}${r.reject_reason || 'rejected'}${r.duplicate_of ? ' (duplicate of ' + r.duplicate_of + ')' : ''}`);
  for (const s of pre) lines.push(`✗ ${s}`);
}
lines.push('');
lines.push(`Submitted by: ${cfg.submitted_by}`);
return [{ json: { text: lines.join('\n') } }];
